actionConfiguration.body:
select *
from public.save_proposal_draft(
	{{
	Number(
		appsmith.store.proposal_save_request?.proposal_id ||
		0
	)
	}},

	'{{
	JSON.stringify(
		appsmith.store.proposal_save_request?.header ||
		{}
	).replaceAll("'", "''")
	}}'::jsonb,

	'{{
	JSON.stringify(
		appsmith.store.proposal_save_request?.menus ||
		[]
	).replaceAll("'", "''")
	}}'::jsonb
);
